/**
 * Parameter types for each tool, mapped by tool name
 */
export type ToolParams = {
  [ACCOUNT_POOL_PICK]: AccountPoolPickParams;
  [ACCOUNT_POOL_MARK_OUT]: AccountPoolMarkOutParams;
  [ACCOUNT_POOL_REPORT_ROOM]: AccountPoolReportRoomParams;
  [ACCOUNT_BUDGET_CHECK_RESERVE]: AccountBudgetCheckReserveParams;
  [ACCOUNT_BUDGET_OBSERVE]: AccountBudgetObserveParams;
  [ACCOUNT_BUDGET_RECORD_USAGE]: AccountBudgetRecordUsageParams;
  [ACCOUNT_BUDGET_RECORD_USAGE_FOR]: AccountBudgetRecordUsageForParams;
  [ACCOUNT_BUDGET_RESERVE]: AccountBudgetReserveParams;
  [ACCOUNT_BUDGET_RESERVE_FOR]: AccountBudgetReserveForParams;
  [ACCOUNT_BUDGET_SET_LIMIT]: AccountBudgetSetLimitParams;
  [ACCOUNT_BUDGET_SETTLE]: AccountBudgetSettleParams;
  [ACCOUNT_BUDGET_SETTLE_FOR]: AccountBudgetSettleForParams;
};

/**
 * Invokes a tool by name using the SDK. A tool whose bindingStatus is
 * unsupported_multipart uploads a file, which tool parameters cannot carry;
 * invokeTool throws for it without sending a request.
 *
 * @param sdk - The initialized SDK instance
 * @param toolName - The namespaced tool name (e.g., "auth.sendMagicLink")
 * @param params - The parameters for the tool
 * @returns The result of the tool invocation
 * @throws Error if the tool name is not recognized
 *
 * @example
 * ```typescript
 * const sdk = new FixturePoolApiSDK({ baseUrl: 'https://api.example.com' });
 * const result = await invokeTool(sdk, 'auth.sendMagicLink', { email: 'user@example.com' });
 * ```
 */
export async function invokeTool<T extends ToolName>(
  sdk: FixturePoolApiSDK,
  toolName: T,
  params: ToolParams[T]
): Promise<unknown> {
  switch (toolName) {
    case ACCOUNT_POOL_PICK:
      return sdk.account.pool.pick({ exclude: (params as AccountPoolPickParams).exclude, match: (params as AccountPoolPickParams).match, prefer: (params as AccountPoolPickParams).prefer });
    case ACCOUNT_POOL_MARK_OUT:
      return sdk.account.pool.markOut((params as AccountPoolMarkOutParams).id, { reason: (params as AccountPoolMarkOutParams).reason, until: (params as AccountPoolMarkOutParams).until });
    case ACCOUNT_POOL_REPORT_ROOM:
      return sdk.account.pool.reportRoom((params as AccountPoolReportRoomParams).id, { near: (params as AccountPoolReportRoomParams).near, reason: (params as AccountPoolReportRoomParams).reason, resetsAt: (params as AccountPoolReportRoomParams).resetsAt, room: (params as AccountPoolReportRoomParams).room });
    case ACCOUNT_BUDGET_CHECK_RESERVE:
      return sdk.account.budget.checkReserve((params as AccountBudgetCheckReserveParams).id, { amount: (params as AccountBudgetCheckReserveParams).amount, meter: (params as AccountBudgetCheckReserveParams).meter });
    case ACCOUNT_BUDGET_OBSERVE:
      return sdk.account.budget.observe((params as AccountBudgetObserveParams).id, { limit: (params as AccountBudgetObserveParams).limit, meter: (params as AccountBudgetObserveParams).meter, resetsAt: (params as AccountBudgetObserveParams).resetsAt, used: (params as AccountBudgetObserveParams).used });
    case ACCOUNT_BUDGET_RECORD_USAGE:
      return sdk.account.budget.recordUsage((params as AccountBudgetRecordUsageParams).id, { amount: (params as AccountBudgetRecordUsageParams).amount, meter: (params as AccountBudgetRecordUsageParams).meter });
    case ACCOUNT_BUDGET_RECORD_USAGE_FOR:
      return sdk.account.budget.recordUsageFor((params as AccountBudgetRecordUsageForParams).id, { amount: (params as AccountBudgetRecordUsageForParams).amount, id: (params as AccountBudgetRecordUsageForParams).id, meter: (params as AccountBudgetRecordUsageForParams).meter, released: (params as AccountBudgetRecordUsageForParams).released, schema: (params as AccountBudgetRecordUsageForParams).schema });
    case ACCOUNT_BUDGET_RESERVE:
      return sdk.account.budget.reserve((params as AccountBudgetReserveParams).id, { amount: (params as AccountBudgetReserveParams).amount, meter: (params as AccountBudgetReserveParams).meter });
    case ACCOUNT_BUDGET_RESERVE_FOR:
      return sdk.account.budget.reserveFor((params as AccountBudgetReserveForParams).id, { amount: (params as AccountBudgetReserveForParams).amount, id: (params as AccountBudgetReserveForParams).id, meter: (params as AccountBudgetReserveForParams).meter, schema: (params as AccountBudgetReserveForParams).schema });
    case ACCOUNT_BUDGET_SET_LIMIT:
      return sdk.account.budget.setLimit((params as AccountBudgetSetLimitParams).id, { limit: (params as AccountBudgetSetLimitParams).limit, meter: (params as AccountBudgetSetLimitParams).meter });
    case ACCOUNT_BUDGET_SETTLE:
      return sdk.account.budget.settle((params as AccountBudgetSettleParams).id, { meter: (params as AccountBudgetSettleParams).meter });
    case ACCOUNT_BUDGET_SETTLE_FOR:
      return sdk.account.budget.settleFor((params as AccountBudgetSettleForParams).id, { amount: (params as AccountBudgetSettleForParams).amount, id: (params as AccountBudgetSettleForParams).id, meter: (params as AccountBudgetSettleForParams).meter, schema: (params as AccountBudgetSettleForParams).schema });
    default:
      throw new Error(`Unknown tool: ${toolName}`);
  }
}

/**
 * Gets the tool definition for a given tool name
 */
export function getToolDefinition(toolName: ToolName): ToolDefinition {
  return toolDefinitions[toolName];
}

/**
 * Gets all tools that require authentication
 */
export function getAuthRequiredTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.requiresAuth);
}

/**
 * Gets all tools that don't require authentication
 */
export function getPublicTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => !t.requiresAuth);
}

/**
 * Gets all tools for a specific namespace
 */
export function getToolsForNamespace(namespace: string): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.namespace === namespace);
}

/**
 * Validates that params contain all required fields for a tool
 */
export function validateToolParams(toolName: ToolName, params: Record<string, unknown>): { valid: boolean; missing: string[] } {
  const tool = toolDefinitions[toolName];
  const required = tool.parameters.required || [];
  const missing = required.filter(field => !(field in params) || params[field] === undefined);
  return { valid: missing.length === 0, missing };
}
